component_data_script:
raw_rows = props.get("facts") or []
if isinstance(raw_rows, str):
	try:
		raw_rows = json.loads(raw_rows)
	except Exception:
		raw_rows = [line for line in raw_rows.split("\n") if line.strip()]
if not isinstance(raw_rows, list):
	raw_rows = []
rows = []
for raw in raw_rows:
	try:
		parts = [part.strip() for part in str(raw).split("|")]
		while len(parts) < 2:
			parts.append("")
		if parts[0] or parts[1]:
			rows.append(parts)
	except Exception:
		continue

facts = []
for parts in rows:
	facts.append({"label": parts[0], "value": parts[1]})
component.facts = facts
layout = str(props.get("layout") or "rows").strip().lower()
if layout not in ["rows", "ledger", "stack", "ink", "cells"]:
	layout = "rows"
component.layout = layout
